query P43Short($owner: String!, $name: String!, $pr: Int!) {
  repository(owner: $owner, name: $name) {
    nameWithOwner
    pullRequest(number: $pr) {
      number state changedFiles
      reviews(first: 1) { totalCount pageInfo { hasNextPage endCursor } nodes { author { login __typename } state } }
      reviewThreads(first: 1) { totalCount pageInfo { hasNextPage endCursor } nodes { path isResolved } }
      labels(first: 1) { totalCount pageInfo { hasNextPage endCursor } nodes { name } }
      timelineItems(first: 1) { totalCount pageInfo { hasNextPage endCursor } nodes { __typename } }
      files(first: 1) { totalCount pageInfo { hasNextPage endCursor } nodes { path changeType } }
      commits(last: 1) {
        nodes {
          commit {
            oid
            statusCheckRollup { contexts(first: 1) { totalCount pageInfo { hasNextPage endCursor } nodes { __typename ... on CheckRun { name } } } }
          }
        }
      }
    }
  }
}

query P43Files($owner: String!, $name: String!, $pr: Int!) {
  repository(owner: $owner, name: $name) {
    nameWithOwner
    pullRequest(number: $pr) {
      number changedFiles
      files(first: 100) { totalCount pageInfo { hasNextPage endCursor } nodes { path changeType additions deletions } }
    }
  }
}
